function tspRng(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; var t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function tspCities(n, w, h, seed){
  var rnd = tspRng(seed||1), cs = [];
  for(var i=0;i<n;i++) cs.push({ x: 20 + rnd()*(w-40), y: 20 + rnd()*(h-40) });
  return cs;
}
function tspDist(a, b){ var dx = a.x-b.x, dy = a.y-b.y; return Math.sqrt(dx*dx+dy*dy); }
function tspLength(cities, tour){
  var L = 0;
  for(var i=0;i<tour.length;i++) L += tspDist(cities[tour[i]], cities[tour[(i+1)%tour.length]]);
  return L;
}
function tspNearest(cities){
  var n = cities.length, used = new Array(n), tour = [0];
  used[0] = true;
  for(var k=1;k<n;k++){
    var last = tour[tour.length-1], best = -1, bd = Infinity;
    for(var i=0;i<n;i++){
      if(!used[i]){
        var d = tspDist(cities[last], cities[i]);
        if(d < bd){ bd = d; best = i; }
      }
    }
    used[best] = true; tour.push(best);
  }
  return tour;
}
function tspTwoOpt(cities, tour, maxPass){
  var t = tour.slice(), n = t.length, improved = true, pass = 0;
  while(improved && pass < (maxPass||50)){
    improved = false; pass++;
    for(var i=0;i<n-1;i++){
      for(var j=i+2;j<n;j++){
        if(i===0 && j===n-1) continue;
        var a = cities[t[i]], b = cities[t[i+1]], c = cities[t[j]], d = cities[t[(j+1)%n]];
        var delta = tspDist(a,c) + tspDist(b,d) - tspDist(a,b) - tspDist(c,d);
        if(delta < -1e-9){
          // reverse segment i+1..j
          for(var lo=i+1, hi=j; lo<hi; lo++, hi--){ var tmp=t[lo]; t[lo]=t[hi]; t[hi]=tmp; }
          improved = true;
        }
      }
    }
  }
  return t;
}
